var ids=['JAH-BM-10','JAH-BM-9','JAH-BM-100'].sort();
console.log('OBSERVED: sorted unpadded IDs = '+JSON.stringify(ids));
assert(JSON.stringify(ids)===JSON.stringify(['JAH-BM-10','JAH-BM-100','JAH-BM-9']),'confirmed: lexicographic misorder');
function pad(n){return 'JAH-BM-'+String(n).padStart(6,'0');}
assert(JSON.stringify([pad(10),pad(9),pad(100)].sort())===JSON.stringify([pad(9),pad(10),pad(100)]),'control: padded IDs sort correctly');

function isPublic(slug){return slug.indexOf('benchmark-database')===0;}
var pub='benchmark-database', sig='benchmark-database-signature';
console.log('OBSERVED: public match='+isPublic(pub)+', signature match='+isPublic(sig));
assert(isPublic(pub)===true && isPublic(sig)===true,'confirmed: both match the naive prefix check');
assert((pub==='benchmark-database')!== (sig==='benchmark-database'),'control: exact equality distinguishes them');

function chunkInclusive(n){var c1=(n>=1&&n<=150)?'chunk-0001':null; var c2=(n>=150&&n<=300)?'chunk-0002':null;
 return [c1,c2].filter(Boolean);}
var got=chunkInclusive(150);
console.log('OBSERVED: ordinal 150 assigned to '+JSON.stringify(got));
assert(got.length===2,'confirmed: boundary ordinal lands in two chunks');
function chunkFixed(n){return 'chunk-'+String(Math.floor((n-1)/150)+1).padStart(4,'0');}
assert(chunkFixed(150)==='chunk-0001'&&chunkFixed(151)==='chunk-0002','control: half-open math assigns exactly one');

var emitted=[];
