console.log('OBSERVED: requested 5, emitted '+emitted.length);
assert(emitted.length===6,'confirmed: <= bound emits n+1');
var ok=[]; for(var j=0;j<5;j++)ok.push(j);
assert(ok.length===5,'control: < bound emits exactly n');

function rankBad(id){var h=0; for(var i=0;i<id.length;i++)h=(h*33+id.charCodeAt(i))>>>0; return h%16;}
var seenZero=false;
for(var i=0;i<200;i++){if(rankBad('JAH-BM-'+i)===0){seenZero=true;break;}}
console.log('OBSERVED: rank 0 produced = '+seenZero);
assert(seenZero===true,'confirmed: modulo-16 yields rank 0 within 200 samples');
function rankGood(id){var h=0; for(var i=0;i<id.length;i++)h=(h*33+id.charCodeAt(i))>>>0; return 1+(h%15);}
var ok=true; for(var j=0;j<200;j++){var r=rankGood('JAH-BM-'+j); if(r<1||r>15)ok=false;}
assert(ok,'control: 1+(h%15) stays in 1..15');

function gen(seed,n){function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
 var r=mulberry32(seed),out=[]; for(var i=0;i<n;i++)out.push(Math.floor(r()*1e9)); return out;}
var a=gen(7,100), b=gen(7,100);
console.log('OBSERVED: two runs with seed 7 identical = '+(JSON.stringify(a)===JSON.stringify(b)));
assert(JSON.stringify(a)===JSON.stringify(b),'confirmed: same seed reproduces identical records');
assert(JSON.stringify(gen(7,100))!==JSON.stringify(gen(8,100)),'control: different seed differs');

