function siblingFixed(slug){return slug.slice(-10)==='-signature'?slug.slice(0,-10):slug+'-signature';}
assert(siblingFixed('benchmark-database-signature')==='benchmark-database','control: fixed version strips the suffix');

var recs=[{built_by:'system-generated'},{built_by:'system-generated'},{built_by:'assistant-built'}];
recs.forEach(function(r){ if(!r.src) r.src='assistant-built'; }); // buggy default
console.log('OBSERVED: generated records labeled = '+JSON.stringify(recs.map(function(r){return r.src;})));
assert(recs[0].src==='assistant-built'&&recs[1].src==='assistant-built','confirmed: generated records mislabeled');
