var pattern='data/x/chunk-NNNN.jsonl.gz';
var files=['data/x/chunks/chunk-0001.jsonl.gz','data/x/chunks/chunk-0002.jsonl.gz'];
function resolve(pat,fs){var re=new RegExp('^'+pat.replace(/NNNN/g,'\\d{4}').replace(/\./g,'\\.')+'$'); return fs.filter(function(f){return re.test(f);});}
var hits=resolve(pattern,files);
